// Meta sends hub.mode, hub.verify_token and hub.challenge as query params.
const q = $input.first().json.query || {};
const ok = q['hub.mode'] === 'subscribe' && !!$env.WHATSAPP_VERIFY_TOKEN && q['hub.verify_token'] === $env.WHATSAPP_VERIFY_TOKEN;
return [{ json: { ok, challenge: String(q['hub.challenge'] || '') } }];

// Pull the first customer message out of the Cloud API payload. Status callbacks
// (sent, delivered, read) and retries of a message id seen in the last hour are dropped.
const value = $input.first().json.body?.entry?.[0]?.changes?.[0]?.value || {};
const m = value.messages?.[0];
if (!m) return [];
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
for (const k in store.seen) if (now - store.seen[k] > 3600000) delete store.seen[k];
if (store.seen[m.id]) return [];
store.seen[m.id] = now;
let text = '', reply_id = null;
if (m.type === 'text') text = m.text?.body || '';
else if (m.type === 'interactive') {
  const r = m.interactive?.button_reply || m.interactive?.list_reply || {};
  text = r.title || ''; reply_id = r.id || null;
} else if (m.type === 'button') text = m.button?.text || '';
return [{ json: {
  message_id: m.id,
  from: m.from,
  name: value.contacts?.[0]?.profile?.name || '',
  text: String(text).slice(0, 600),
  reply_id,
  type: m.type,
} }];

