// Guardrails run in code, after the model, so the model never decides what is allowed.
const msg = $('Parse Message').first().json;
const text = msg.text;
const low = text.toLowerCase();

// Knowledge base: replace with your own entries (or load them from a sheet).
const KB = [
  { id: 'shipping', keywords: ['ship','shipping','delivery','deliver','pincode','courier','charges','free'], en: 'We ship across India. Metro cities get delivery in 2 to 4 working days and other pin codes in 4 to 7. Shipping is free above ₹499, otherwise ₹49.' },
  { id: 'cod', keywords: ['cod','cash','payment','upi','card'], en: 'Cash on delivery is available on orders up to ₹3,000 with a ₹30 handling fee. UPI, cards and net banking work for every order.' },
  { id: 'returns', keywords: ['return','returns','exchange','policy','refund','damaged'], en: 'Unopened products can be returned within 7 days of delivery. Refunds reach the original payment method in 5 to 7 working days after pickup.' },
  { id: 'offers', keywords: ['discount','coupon','code','offer','sale','promo'], en: 'Use FIRST10 for 10% off your first order. Codes cannot be combined.' },
];
const STOP = new Set('a an the is are to of for in on at and or i me my we you your do does can what which how when where please hai kya ka ki ke ko se mein aap mera mujhe kab kaise'.split(' '));

// 1. Model output, with a rule-based fallback.
let intent = null, confidence = 0, source = 'model';
try {
  const raw = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text;
  const o = JSON.parse(raw);
  if (['faq','order_status','appointment','refund','complaint','human'].includes(o.intent)) { intent = o.intent; confidence = Number(o.confidence) || 0; }
} catch (e) {}
if (!intent) {
  source = 'rules';
  const rules = [
    ['human', /\b(human|person|agent|talk to|speak to|baat kar|manager)\b/],
    ['complaint', /\b(bad|worst|rash|damaged|broken|fraud|angry|bekar|ghatiya|complain)/],
    ['refund', /\b(refund|money back|paise wapas|withdraw)/],
    ['appointment', /\b(book|appointment|slot|consult|demo class|check-?up)/],
    ['order_status', /\b(where|track|status|kab aayega|order)\b|[a-z]{2,4}-\d{4,6}/],
  ];
  const hit = rules.find(([, re]) => re.test(low));
  intent = hit ? hit[0] : 'faq';
  confidence = hit ? 0.8 : (/\?\s*$/.test(text) ? 0.7 : 0.3);
}
if (msg.reply_id) {
  const p = msg.reply_id.split(':')[0];
  intent = { slot: 'appointment', refund: 'refund', order: 'order_status' }[p] || intent; confidence = 1; source = 'button';
}
const hinglish = (low.match(/\b(hai|kya|mera|meri|kab|kaise|nahi|chahiye|aap|mujhe|karo|aayega|kitna|wapas)\b/g) || []).length >= 2;
const lang = hinglish ? 'hinglish' : 'en';
const order_id = (text.match(/\b([A-Za-z]{2,4})-?(\d{4,6})\b/) || []).slice(1, 3).join('-').toUpperCase() || null;
const slot_id = msg.reply_id && msg.reply_id.startsWith('slot:') ? msg.reply_id.slice(5) : null;
const wa = (body) => ({ messaging_product: 'whatsapp', to: msg.from, type: 'text', text: { body } });
const base = { ...msg, intent, confidence, source, lang, order_id, slot_id, guardrails: [] };

// 2. Guardrails.
if (/ignore (all |your |previous )*(instructions|rules)|system prompt|you are now|jailbreak/i.test(text)) {
  return [{ json: { ...base, route: 'direct', guardrails: ['injection_blocked'], whatsapp: wa('I can only help with our products, orders, refunds and bookings, using our published policies.') } }];
}
if (intent === 'human' || intent === 'complaint') {
  return [{ json: { ...base, route: 'handoff', reason_code: intent === 'human' ? 'asked_for_human' : 'complaint', priority: intent === 'complaint' ? 'high' : 'normal' } }];
}
if (/\b(pregnan|breastfeed|painkiller|medicine|dosage|antibiotic|prescri)/i.test(text) && intent === 'faq') {
  return [{ json: { ...base, route: 'direct', guardrails: ['medical_refused'], whatsapp: wa('I cannot give medical advice. Please check with your doctor. Reply "talk to a person" to reach our team.') } }];
}
if (confidence < 0.55) {
  return [{ json: { ...base, route: 'handoff', reason_code: 'low_confidence', priority: 'normal' } }];
}
if (intent === 'faq') {
  const q = [...new Set(low.replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter((w) => w.length > 1 && !STOP.has(w)))];
  const scored = KB.map((k) => ({ k, score: q.length ? q.filter((w) => k.keywords.some((x) => x === w || (w.length >= 4 && (x.startsWith(w) || w.startsWith(x))))).length / q.length : 0 }))
    .sort((a, b) => b.score - a.score);
  const passages = scored.filter((s) => s.score >= 0.5).slice(0, 2).map((s) => ({ id: s.k.id, text: s.k.en }));
  if (!passages.length) {
    return [{ json: { ...base, route: 'direct', guardrails: ['not_in_kb'], whatsapp: wa('I do not have verified information about that, so I will not guess. Reply "talk to a person" and our team will answer.') } }];
  }
  return [{ json: { ...base, route: 'faq', passages } }];
}
return [{ json: { ...base, route: intent === 'appointment' ? 'appointment' : 'order' } }];

