// Every number in the model's answer must appear in the passages; otherwise send the KB text verbatim.
const ctx = $('Route + Guardrails').first().json;
const passages = ctx.passages || [];
let answer = passages.map((p) => p.text).join(' ');
let grounded = 'kb_verbatim';
try {
  const o = JSON.parse($input.first().json.candidates?.[0]?.content?.parts?.[0]?.text);
  const nums = (s) => (String(s).match(/\d[\d,]*/g) || []).map((n) => n.replace(/,/g, ''));
  const allowed = new Set(passages.flatMap((p) => nums(p.text)));
  const idsOk = Array.isArray(o.used_ids) && o.used_ids.every((id) => passages.some((p) => p.id === id));
  if (o.covered !== false && typeof o.answer === 'string' && idsOk && nums(o.answer).every((n) => allowed.has(n))) { answer = o.answer.slice(0, 700); grounded = 'model_checked'; }
} catch (e) {}
return [{ json: { ...ctx, grounded, whatsapp: { messaging_product: 'whatsapp', to: ctx.from, type: 'text', text: { body: answer } } } }];

// Expects the orders API to return { orders: [{ id, phone, items, amount, status, eta, delivered_at }] }.
const ctx = $('Route + Guardrails').first().json;
const limit = Number($env.REFUND_AUTO_LIMIT) || 1500;
const res = $input.first().json || {};
const all = Array.isArray(res.orders) ? res.orders : [];
// Identity check: only orders on the sender's own WhatsApp number.
const mine = all.filter((o) => String(o.phone || '').replace(/\D/g, '').endsWith(String(ctx.from).slice(-10)));
const wa = (body) => ({ messaging_product: 'whatsapp', to: ctx.from, type: 'text', text: { body } });
if (res.error || !mine.length) {
  return [{ json: { ...ctx, needs_human: false, whatsapp: wa(ctx.order_id ? `I could not find ${ctx.order_id} on this number. Please check the ID.` : 'I could not find an order on this number. Please share your order ID.') } }];
}
const o = ctx.order_id ? (mine.find((x) => x.id === ctx.order_id) || mine[0]) : mine[0];
if (ctx.intent === 'refund') {
  if (Number(o.amount) > limit) {
    return [{ json: { ...ctx, needs_human: true, route: 'handoff', reason_code: 'refund_over_limit', priority: 'normal', order: o } }];
  }
  return [{ json: { ...ctx, needs_human: false, whatsapp: wa(`Refund of ₹${o.amount} for ${o.id} is requested. Our team will confirm pickup, and it usually reflects in 5 to 7 working days.`) } }];
}
const eta = o.eta ? `, expected ${o.eta}` : '';
return [{ json: { ...ctx, needs_human: false, whatsapp: wa(`Order ${o.id} (${o.items}, ₹${o.amount}) is ${String(o.status).replace(/_/g, ' ')}${eta}.`) } }];

// Expects { ok, booking: { id, label } } or { ok: false, error: 'slot_taken' }.
const ctx = $('Route + Guardrails').first().json;
const r = $input.first().json || {};
const body = r.ok && r.booking
  ? `Booked. Your slot is ${r.booking.label} (ID ${r.booking.id}). Reply CANCEL to cancel.`
  : 'That slot was just taken. Reply "book" to see the next open slots.';
return [{ json: { ...ctx, whatsapp: { messaging_product: 'whatsapp', to: ctx.from, type: 'text', text: { body } } } }];

// Expects { slots: [{ id, label }] }. Sends a WhatsApp interactive list (max 10 rows, 24-char titles).
const ctx = $('Route + Guardrails').first().json;
const slots = ($input.first().json.slots || []).slice(0, 10);
if (!slots.length) {
  return [{ json: { ...ctx, whatsapp: { messaging_product: 'whatsapp', to: ctx.from, type: 'text', text: { body: 'No slots are open this week. Reply "talk to a person" and our team will call you.' } } } }];
}
return [{ json: { ...ctx, whatsapp: {
  messaging_product: 'whatsapp', to: ctx.from, type: 'interactive',
  interactive: {
    type: 'list',
    body: { text: 'Here are the next open slots. Pick one to book.' },
    action: { button: 'See slots', sections: [{ title: 'Open slots', rows: slots.map((s) => ({ id: 'slot:' + s.id, title: String(s.label).slice(0, 24) })) }] },
  },
} } }];

const ctx = $input.first().json;
const id = 'HO-' + String(Date.now()).slice(-5);
const masked = '+' + String(ctx.from).slice(0, 2) + ' ' + String(ctx.from).slice(2, 4) + 'xxx xx' + String(ctx.from).slice(-3);
const reasons = { asked_for_human: 'Customer asked for a person', complaint: 'Complaint', low_confidence: 'Intent unclear', refund_over_limit: 'Refund above the auto limit' };
const slack = {
  text: `Handoff ${id}: ${reasons[ctx.reason_code] || ctx.reason_code}`,
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: `WhatsApp handoff ${id}` } },
    { type: 'section', fields: [
      { type: 'mrkdwn', text: `*Reason*\n${reasons[ctx.reason_code] || ctx.reason_code}` },
      { type: 'mrkdwn', text: `*Priority*\n${ctx.priority || 'normal'}` },
      { type: 'mrkdwn', text: `*Customer*\n${ctx.name || 'Unknown'} · ${masked}` },
      { type: 'mrkdwn', text: `*Intent*\n${ctx.intent} (${Number(ctx.confidence).toFixed(2)}, ${ctx.source})` },
    ] },
    { type: 'section', text: { type: 'mrkdwn', text: `*Last message*\n>${String(ctx.text).slice(0, 300)}` } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: 'Bot paused for this chat. Reply from WhatsApp Business inbox.' }] },
  ],
};
return [{ json: { ...ctx, ticket_id: id, slack } }];

const ctx = $('Build Handoff Ticket').first().json;
const body = ctx.lang === 'hinglish'
  ? `Maine aapki baat team tak pahuncha di hai (ticket ${ctx.ticket_id}). Ek team member jaldi yahin reply karega.`
  : `${ctx.reason_code === 'complaint' ? 'I am sorry about this experience. ' : ''}I have passed this to our team (ticket ${ctx.ticket_id}). A person will reply here shortly.`;
return [{ json: { ...ctx, whatsapp: { messaging_product: 'whatsapp', to: ctx.from, type: 'text', text: { body } } } }];
